if (this.generating) return
this.generating = true
setTimeout(() => {
    const t0 = trkNow()
    const issues = trkGenerate(count)
    const t1 = trkNow()
    this.adopt(issues)
    this.loadMs = Math.round(t1 - t0)
    this.adoptMs = Math.round(trkNow() - t1)
    this.generating = false
    }, 0)

let rows = this.issuesOf()
if (byStatus != "" || byAssignee != "" || byLabel != "") {
    rows = rows.filter((it) =>
        (byStatus == "" || it.status == byStatus) &&
        (byAssignee == "" || it.assignee == byAssignee) &&
        (byLabel == "" || (it.labels ?? []).includes(byLabel)))
    }
// the query narrows like any other filter (a tracker searches by
// hiding what doesn't match, not by bolding what does); the scan is
// timed and the number rides out with the value — pure, no clocks
let searchMs = 0
if (query.trim() != "") {
    const t0 = trkNow()
    const needle = query.trim().toLowerCase()
    rows = rows.filter((it) => trkHaystack(it).includes(needle))
    searchMs = Math.max(0, Math.round((trkNow() - t0) * 10) / 10)
    }
// Every comparator is ascending — least-interesting first: oldest,
// lowest priority, A→Z. `desc` then reverses, uniformly, with no key
// carrying a special case (so a new sort field inherits the rule).
const RANK = ({ P0: 3, P1: 2, P2: 1, P3: 0 })
const asc = sortOn == "priority" ? (a, b) => RANK[a.priority] - RANK[b.priority] || a.updated - b.updated
    : sortOn == "title" ? (a, b) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0)
    : (a, b) => a.updated - b.updated
rows = [...rows].sort(sortDir == "desc" ? (a, b) => asc(b, a) : asc)
if (grouping != "status") return ({ rows: rows, total: rows.length, searchMs: searchMs })
const order = ["open", "in-progress", "blocked", "closed"]
const out = []
for (const st of order) {
    const members = rows.filter((it) => it.status == st)
    if (members.length == 0) continue
    out.push(({ kind: "hdr", id: "hdr:" + st, status: st, count: members.length }))
    if (!this.isCollapsed(st)) out.push(...members)
    }
return ({ rows: out, total: rows.length, searchMs: searchMs })

const clean = sel == null ? null : (sel).filter((r) => r.kind != "hdr")
this.selection = clean != null && (clean).length > 0 ? clean : null
if (clean != null && (clean).length > 1) this.editing = false
this.selected = this.selection != null ? (this.selection)[(this.selection).length - 1] : null
if (this.selection == null) this.closeDetail()
// The editor follows the selection: which issue is open is derived from
// it, so the draft has to move with it or the open row shows another
// issue's fields. An in-flight edit is discarded here, and equally
// when you open a different issue — a real gap, not a decision: the
// draft is one slot, so there is nowhere to keep an edit you have
// navigated away from. Closing it means a draft per issue (or a dirty
// guard), which is its own piece of work.
else if (this.editing && (clean).length == 1) this.seedDraft()

const sel = this.selection ?? []
const issues = this.issuesOf()
for (const r of sel) {
    const i = issues.findIndex((it) => (it).id == (r).id)
    if (i < 0) continue
    if (field == "label") {
        const ls = [...(((issues[i]).labels) ?? [])]
        if (!ls.includes(v)) ls.push(v)
        this.db.set(["issues", i, "labels"], ls)
        } else {
        this.db.set(["issues", i, field], v)
        }
    const up = ((issues[i]).updated ?? 0) + 1
    this.db.set(["issues", i, "updated"], up)
    if (field == "status") this.db.set(["issues", i, "closedAt"], v == "closed" ? up : null)
    }

const m = this.bulkMenu
m.items = [
    ({ id: "s:open", label: "Set open" }),
    ({ id: "s:in-progress", label: "Set in-progress" }),
    ({ id: "s:blocked", label: "Set blocked" }),
    ({ id: "s:closed", label: "Set closed" }),
    ({ divider: true }),
    ...TRK_LABELS.slice(0, 8).map((l) => ({ id: "l:" + l, label: "Label: " + l })),
    ({ divider: true }),
    ({ id: "delete", label: "Delete…" }),
]
m.picked = (id) => {
    if (id.startsWith("s:")) this.root.bulkSet("status", id.slice(2))
    else if (id.startsWith("l:")) this.root.bulkSet("label", id.slice(2))
    else if (id == "delete") this.root.deleteSelection()
    }
m.openFor(anchor)

const rec = (row).member()
if (this.selection == null || !(this.selection).some((r) => (r).id == (rec).id)) this.takeSelection([rec])
const m = this.ctx
m.picked = (id) => {
    if (id.startsWith("s:")) this.root.bulkSet("status", id.slice(2))
    else if (id == "delete") this.root.deleteSelection()
    }
m.open(row, e)

const m = this.facetMenu
const names = this.assignees()
m.items = [({ id: "", label: "Anyone", checked: this.root.fAssignee == "" }), ({ id: "d", divider: true }),
    ...names.map((p) => ({ id: p, label: p, icon: "PersonIcon", props: ({ name: p }), checked: this.root.fAssignee == p }))]
m.picked = (id) => { this.root.fAssignee = id }
m.openFor(anchor)

// ⌘K or "/" reach the search field from anywhere — but "/" is a
// character, so it only counts when nothing is taking text
if ((e.meta || e.ctrl) && e.code == "KeyK") { Focus.focus(this.root.bar.omni) }
// Escape unwinds the innermost layer first: the open editor, then
// a selection, then the query, then the facet filters. Anything
// else and a keystroke meant for the thing in front of you lands
// on something behind it.
else if (e.key == "Escape") {
    if (this.root.editing) this.root.closeDetail()
    else if (this.root.selCount > 0) this.root.takeSelection(null)
    else if (this.root.query != "") { this.root.query = ""; this.root.bar.omni.text = "" }
    else if (this.root.fStatus != "" || this.root.fAssignee != "" || this.root.fLabel != "") this.root.clearAll()
    }
